attempts.source:
sketch:
    claim:
        ? forall x range(-2, 1):
            x $in {-2, -1, 0}
        expand: x $in range(-2, 1)
        by cases:
            ? x $in {-2, -1, 0}
            case x = -2:
                x $in {-2, -1, 0}
            case x = -1:
                x $in {-2, -1, 0}
            case x = 0:
                x $in {-2, -1, 0}
    by enumerate finite_set:
        ? forall x {-2, -1, 0}:
            x $in range(-2, 1)
    by extension range(-2, 1) = {-2, -1, 0}

