promoted.source:
sketch:
    by contra:
        ? {1} != {2}
        1 $in {1}
        1 $in {2}
        impossible 1 $in {2}
    by extension:
        ? family_union({{1}, {2}}) = {1, 2}
        claim:
            ? forall x family_union({{1}, {2}}):
                x $in {1, 2}
            obtain A from exist A {{1}, {2}} st {x $in A}
            A = {1} or A = {2}
            by cases:
                ? x $in {1, 2}
                case A = {1}:
                    x $in {1}
                    x = 1
                case A = {2}:
                    x $in {2}
                    x = 2
